import{_ as r,a0 as e,w as s,s as u,I as p,x as o,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"解密 top 命令 | LCTT x X-CMD","titleTemplate":false,"description":"解密 top 命令 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"解密 top 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"解密 top 命令 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Deciphering Top","title":"解密 top 命令","tag":"201311","desc":""},"relativePath":"201311/Deciphering Top.md","filePath":"[post].md"}'),m={name:"201311/Deciphering Top.md"};function d(a,t,f,C,g,T){const l=e("Link");return s(),u("div",null,[t[15]||(t[15]=p("h1",{id:"解密-top-命令",tabindex:"-1"},[o('解密"top"命令 '),p("a",{class:"header-anchor",href:"#解密-top-命令","aria-label":"Permalink to “解密top命令”"},"​")],-1)),t[16]||(t[16]=p("p",null,'当对服务器的性能好奇时，我第一个想到的是"top"命令。top不是最好的，它不是一个长期的快照，但是它提供了服务器的一个不错的时间点快照，并且试着提供了告诉"现在在发生什么？"。不幸地，如果你没有深入了解不同显示域的意义，top的输出很容易被误解。',-1)),p("p",null,[t[1]||(t[1]=o("我不会完整解读top命令的",-1)),n(l,{href:"http://www.linuxmanpages.com/man1/top1.php"},{default:i(()=>[...t[0]||(t[0]=[o("man page",-1)])]),_:1}),t[2]||(t[2]=o("，当你和时间和意愿时，它一直在那等着你。我想要做的是指出一些我如何得到系统的快速概况的几个要点，并希望得到我接下来该怎么做的指示。top是我在故障排除时的第一站，但这很少会是我唯一的一站。",-1))]),p("p",null,[n(l,{href:"http://www.flickr.com/photos/51724787@N06/10847969205/"},{default:i(()=>[...t[3]||(t[3]=[p("img",{src:"http://farm4.staticflickr.com/3827/10847969205_5005a709c2_o.png",alt:""},null,-1)])]),_:1})]),t[17]||(t[17]=p("p",null,'top命令我第一个看的是平均负载(load average)，它在右上角的屏幕上。平均负载的计算是基于统计搜集到的数量，但是通常可以认为是CPU被请求工作的数量。如果你的机器有一个单核CPU，那么平均负载是1就意味着机器满载的，并且有足够的能力在采样时间内完成任务。同样地，如果平均负载是2，那对单核的CPU是超载的，并需要2个可用内核才能在同样的采样时间内完成的要求的任务。随着8、16、32核的发售，我会在判断平均负载的时候就要注意一下。比如我需要去检测时，我会在top里按了数字"1"，这会列出所有CPU核列表，这样我就可以得到一个快速计数用于比较负载。',-1)),t[18]||(t[18]=p("p",null,'我检查的第二项是上面列出来的内容的第9列，标记着"%CPU"那个。对这一列的解释是很模糊的:',-1)),t[19]||(t[19]=p("blockquote",null,[p("p",null,"任务所分享的上次屏幕刷新后的CPU运行时间，以全部的CPU时间百分比表示。在一个真正的SMP（多处理器）环境中，如果'Irix mode'是关闭的，top会在'Solaris mode'下运行，这里一个任务的cpu使用率将除以全部的CPU数量。你可以用'I'（大写字母I）这个交互命令触发Irix或Solaris模式。")],-1)),t[20]||(t[20]=p("p",null,"一点也不清楚，是么？这里要记住的主要意思是，如果单个进程由于某个原因或者其他因素占用率升高，那么他很有可能会以%CPU很高的数字显示在top的第一行。",-1)),t[21]||(t[21]=p("p",null,'我下一个注意到的区域是"Cpu(s):"这一行，在头部信息的中间。特别地，我对%us、sy%、%id、和%wa感兴趣，它们分别是用户进程、系统进程、空闲时间和CPU用于等待I/O流执行的时间比例。这个百分比应该接近于0，高于5%时需要密切关注。',-1)),t[22]||(t[22]=p("p",null,"最后，我想要看看系统up时间，这显示在左上角。如果我对一台服务器有疑问，并且这台服务器最近重启过，这里可能会发现一些什么，或许是一个守护进程没有启动。",-1)),t[23]||(t[23]=p("p",null,"这些检查只需要几秒。如果我只是观察，我可能让top运行几分钟并观察进程、CPU和负载，但是通常地我很快地进入和退出top。top是给你一个系统健康概况的那些奇妙系统管理员工具之一，并允许你快速诊断潜在的问题。",-1)),t[24]||(t[24]=p("hr",null,null,-1)),p("p",null,[t[5]||(t[5]=o("via: ",-1)),n(l,{href:"http://ostatic.com/blog/deciphering-top"},{default:i(()=>[...t[4]||(t[4]=[o("http://ostatic.com/blog/deciphering-top",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=o("译者：",-1)),n(l,{href:"https://github.com/geekpi"},{default:i(()=>[...t[6]||(t[6]=[o("geekpi",-1)])]),_:1}),t[9]||(t[9]=o(" 校对：",-1)),n(l,{href:"https://github.com/wxy"},{default:i(()=>[...t[7]||(t[7]=[o("wxy",-1)])]),_:1})]),p("p",null,[t[12]||(t[12]=o("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[10]||(t[10]=[o("LCTT",-1)])]),_:1}),t[13]||(t[13]=o(" 原创翻译，",-1)),n(l,{href:"http://linux.cn/"},{default:i(()=>[...t[11]||(t[11]=[o("Linux中国",-1)])]),_:1}),t[14]||(t[14]=o(" 荣誉推出",-1))])])}const U=r(m,[["render",d]]);export{w as __pageData,U as default};
